from __future__ import annotations

import argparse
import http.client
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

TIMEOUT = 10


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args, **kwargs):
        return None


def _dump(obj):
    return json.dumps(obj, separators=(",", ":"), ensure_ascii=True)


def _call(args, method, path, body=None, headers=None):
    hdrs = dict(headers or {})
    if args.token:
        hdrs["Authorization"] = "Bearer " + args.token
    data = None
    if body is not None:
        data = _dump(body).encode("utf-8")
        hdrs["Content-Type"] = "application/json"
    req = urllib.request.Request(args.server.rstrip("/") + path, data=data, headers=hdrs, method=method)
    opener = urllib.request.build_opener(_NoRedirect)
    try:
        with opener.open(req, timeout=TIMEOUT) as resp:
            raw = resp.read()
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        try:
            raw = _dump(json.loads(raw))
        except ValueError:
            pass
        print(raw, file=sys.stderr)
        return 1
    except (urllib.error.URLError, OSError, http.client.HTTPException) as e:
        print("error: %s" % e, file=sys.stderr)
        return 3
    if raw:
        try:
            sys.stdout.write(_dump(json.loads(raw)) + "\n")
        except ValueError as e:
            print("error: invalid response: %s" % e, file=sys.stderr)
            return 3
    return 0


def _token_create(a):
    return _call(a, "POST", "/v1/tokens", headers={"X-Admin-Key": a.admin_key})


def _shorten(a):
    body = {"url": a.url}
    if a.slug is not None:
        body["slug"] = a.slug
    if a.expires_in is not None:
        body["expires_in"] = a.expires_in
    return _call(a, "POST", "/v1/links", body)


def _list(a):
    return _call(a, "GET", "/v1/links")


def _stats(a):
    return _call(a, "GET", "/v1/links/" + urllib.parse.quote(a.slug, safe=""))


def _delete(a):
    return _call(a, "DELETE", "/v1/links/" + urllib.parse.quote(a.slug, safe=""))


def register(sub):
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--server", default=None)
    common.add_argument("--token", default=None)

    def add(name, func, needs_token=True):
        p = sub.add_parser(name, parents=[common])
        p.set_defaults(func=_resolve(func, p, needs_token))
        return p

    add("token", None)  # replaced below
    sub.choices.pop("token")
    tp = sub.add_parser("token", parents=[common])
    tsub = tp.add_subparsers(dest="token_command", required=True)
    c = tsub.add_parser("create", parents=[common])
    c.add_argument("--admin-key", required=True)
    c.set_defaults(func=_resolve(_token_create, c, False))

    p = add("shorten", _shorten)
    p.add_argument("url")
    p.add_argument("--slug")
    p.add_argument("--expires-in", type=int)
    add("list", _list)
    add("stats", _stats).add_argument("slug")
    add("delete", _delete).add_argument("slug")


def _resolve(func, parser, needs_token):
    def run(args):
        args.server = args.server or os.environ.get("LINKVAULT_SERVER")
        args.token = args.token or os.environ.get("LINKVAULT_TOKEN")
        if not args.server:
            parser.error("server required (--server or LINKVAULT_SERVER)")
        if needs_token and not args.token:
            parser.error("token required (--token or LINKVAULT_TOKEN)")
        return func(args)
    return run
